3	 *
4	 * 6FHD MIPI DSI panel driver (1080x2160/1080x1920).
5	 * Panel init sequence: 0x11 (120ms) -> 0x29 (RK3566 DTSI).
6	 ****************************************************************************/
7	
8	#include "mipi_6fhd.h"
9	
10	static void lcd_power_on(u32 sel);
11	static void lcd_power_off(u32 sel);
12	static void lcd_bl_open(u32 sel);
13	static void lcd_bl_close(u32 sel);
14	static void lcd_panel_init(u32 sel);
15	static void lcd_panel_exit(u32 sel);
16	
17	#define panel_reset(sel, val) sunxi_lcd_gpio_set_value(sel, 0, val)
18	
19	static void lcd_cfg_panel_info(struct panel_extend_para *info)
20	{
21		/* 不使用 Cmap/Gamma 映射，避免 DE 引入额外的 stride/颜色转换 */
22		memset(info, 0, sizeof(struct panel_extend_para));
23	}
24	
25	static s32 lcd_open_flow(u32 sel)
26	{
27		LCD_OPEN_FUNC(sel, lcd_power_on, 20);
28		LCD_OPEN_FUNC(sel, lcd_panel_init, 50);
29		LCD_OPEN_FUNC(sel, sunxi_lcd_tcon_enable, 30);
30		LCD_OPEN_FUNC(sel, lcd_bl_open, 0);
31		return 0;
32	}
33	
34	static s32 lcd_close_flow(u32 sel)
35	{
36		LCD_CLOSE_FUNC(sel, lcd_bl_close, 0);
37		LCD_CLOSE_FUNC(sel, sunxi_lcd_tcon_disable, 0);
38		LCD_CLOSE_FUNC(sel, lcd_panel_exit, 100);
39		LCD_CLOSE_FUNC(sel, lcd_power_off, 200);
40		return 0;
41	}
42	
43	static void lcd_power_on(u32 sel)
44	{
45		/* 对齐 RK3566 DTSI: reset-delay-ms = <120> */
46		sunxi_lcd_power_enable(sel, 0);      /* IOVDD 1.8V (DCDC1) */
47		sunxi_lcd_delay_ms(15);
48		sunxi_lcd_power_enable(sel, 1);      /* 核心 1.8V (DCDC3) */
49		sunxi_lcd_delay_ms(15);
50	
51		sunxi_lcd_pin_cfg(sel, 1);           /* MIPI 引脚配置 */
52		sunxi_lcd_delay_ms(20);
53	
54		/* 标准硬件复位负脉冲 */
55		panel_reset(sel, 1);
56		sunxi_lcd_delay_ms(20);
57		panel_reset(sel, 0);                 /* 拉低复位 */
58		sunxi_lcd_delay_ms(50);
59		panel_reset(sel, 1);                 /* 释放复位 */
60		sunxi_lcd_delay_ms(120);             /* 对齐 dtsi reset-delay */
61	
62		sunxi_lcd_power_enable(sel, 2);      /* AVDD 3.3V (DCDC2) */
63		sunxi_lcd_delay_ms(20);
64	}
65	
66	static void lcd_power_off(u32 sel)
67	{
68		sunxi_lcd_pin_cfg(sel, 0);
69		sunxi_lcd_delay_ms(10);
70		panel_reset(sel, 0);
71		sunxi_lcd_delay_ms(10);
72		sunxi_lcd_power_disable(sel, 2);
73		sunxi_lcd_power_disable(sel, 1);
74		sunxi_lcd_power_disable(sel, 0);
75	}
76	
77	static void lcd_bl_open(u32 sel)
78	{
79		sunxi_lcd_pwm_enable(sel);
80		sunxi_lcd_backlight_enable(sel);
81	}
82	
83	static void lcd_bl_close(u32 sel)
84	{
85		sunxi_lcd_backlight_disable(sel);
86		sunxi_lcd_pwm_disable(sel);
87	}
88	
89	static void lcd_panel_init(u32 sel)
90	{
91		/* DSI 时钟在 DCS 命令前使能 */
92		sunxi_lcd_dsi_clk_enable(sel);
93		sunxi_lcd_delay_ms(20);
94	
95		sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_EXIT_SLEEP_MODE);
96		sunxi_lcd_delay_ms(120);             /* 必须严格等待 120ms */
97	
98		sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_ON);
99		sunxi_lcd_delay_ms(20);
100	}
101	
102	static void lcd_panel_exit(u32 sel)
103	{
104		sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_OFF);
105		sunxi_lcd_delay_ms(20);
106		sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_ENTER_SLEEP_MODE);
107		sunxi_lcd_delay_ms(80);
108	}
109	
110	static s32 lcd_user_defined_func(u32 sel, u32 para1, u32 para2, u32 para3)
111	{
112		return 0;
113	}
