/* PB4: 5V->1.8V LDO EN (no touch reset). PB5: INT (active low). */
#define TP_LDO_EN   GPIOB(4)
#define TP_INT      GPIOB(5)

#define TYPE_STATUS_EVENT_ACK       1
#define SEC_TS_WAIT_RETRY_CNT       100
#define SEC_TS_MAX_EVENT_LOOP       128

struct sec_ts_event_coordinate_s
{
  uint8_t tchsta:3;
  uint8_t ttype:3;
  uint8_t eid:2;
  uint8_t tid:4;
  uint8_t nt:4;
  uint8_t x_11_4;
  uint8_t y_11_4;
  uint8_t y_3_0:4;
  uint8_t x_3_0:4;
  uint8_t z;
  uint8_t major;
  uint8_t minor;
} __attribute__((packed));

struct sec_ts_touch_dev_s
{
  struct touch_lowerhalf_s lower;
  FAR struct i2c_master_s *i2c;
  uint32_t frequency;
  struct work_s work;
  uint32_t irq;
  uint8_t touch_functions;
  bool slot_active[SEC_TS_MAX_TOUCH_POINTS];
};

static struct sec_ts_touch_dev_s g_sec_ts_touch =
{
  .lower.maxpoint = SEC_TS_MAX_TOUCH_POINTS,
  .lower.control = NULL,
  .lower.write = NULL,
  .frequency = SEC_TS_I2C_FREQUENCY,
};

